const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });
// List all tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table' ORDER BY name\").all();
console.log('Tables:', tables.map(t => t.name).join(', '));
// Get retail-relevant table schemas
for (const t of ['rt_users','rt_orders','rt_products','rt_variants','order_payments','order_fulfillments']) {
  try {
    const info = db.prepare('PRAGMA table_info(' + t + ')').all();
    console.log('\n=== ' + t + ' ===');
    info.forEach(c => console.log('  ' + c.name + ' (' + c.type + ')'));
  } catch(e) {}
}
"

