  const oids = orders.map(o => o.order_id);
  for (const oid of oids) {
    const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = ?\").all(oid);
    console.log('\nItems for ' + oid + ':', JSON.stringify(items, null, 2));
  }
}

